'use strict';
const KEY='mld371-guide-v1';
const checks=[...document.querySelectorAll('[data-check]')];
let state={checks:{},os:'windows'}, storageOK=true;
let feedbackTimer;
const announce=message=>{clearTimeout(feedbackTimer);document.querySelector('#feedback').textContent=message;feedbackTimer=setTimeout(()=>{document.querySelector('#feedback').textContent='';},6000);};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&typeof saved==='object'){state.checks=saved.checks&&typeof saved.checks==='object'?saved.checks:{};state.os=saved.os==='mac'?'mac':'windows';}localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}if(!storageOK)document.querySelector('#storage-note').textContent='Storage unavailable. Checkmarks work for this visit only. Completion is self-reported.';}
function update(){let done=0;checks.forEach(c=>{c.checked=state.checks[c.dataset.check]===true;if(c.checked)done++;});const percent=Math.round(done/checks.length*100);document.querySelector('#overall').value=percent;document.querySelector('#overall-label').textContent=percent+'%';document.querySelectorAll('section').forEach(s=>{const all=[...s.querySelectorAll('[data-check]')];let label=s.querySelector('.section-progress');if(!label){label=document.createElement('p');label.className='section-progress';s.append(label);}label.textContent=all.filter(c=>c.checked).length+' / '+all.length+' checkpoints · self-reported';});}
checks.forEach(c=>c.addEventListener('change',()=>{state.checks[c.dataset.check]=c.checked;save();update();}));
const os=document.querySelector('#os');function showOS(){document.querySelectorAll('[data-os]').forEach(el=>el.hidden=el.dataset.os!==state.os);os.value=state.os;}os.addEventListener('change',()=>{state.os=os.value;showOS();save();announce('Showing '+(state.os==='mac'?'macOS':'Windows')+' instructions.');});
document.querySelectorAll('.codebox').forEach((box,i)=>{const button=document.createElement('button');button.type='button';button.textContent='Copy';button.setAttribute('aria-label','Copy '+(box.dataset.label||'example '+(i+1)));box.querySelector('.codehead').append(button);button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(box.querySelector('pre').textContent);announce('Copied '+(box.dataset.label||'example')+'.');}catch{announce('Copy unavailable. Select the text and use your computer’s Copy command.');}});});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());dialog.addEventListener('close',()=>{if(dialog.returnValue==='reset'){state.checks={};save();update();announce('Progress reset. Your project files are unchanged.');}});
function active(){document.querySelectorAll('nav a').forEach(a=>{if(a.hash===location.hash)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}addEventListener('hashchange',active);active();showOS();save();update();
